// Filtra rows que llevan >=4h en awaiting_join y todavía no se les ha hecho
// la re-invitación de las 4h.
//
// Limitamos también a edad <24h para evitar pisar la rama de Slack 24h.
// Si por alguna razón no se ejecutó este branch a tiempo, no pasa nada: la
// rama 24h alertará igual y el SDR sabrá lo que pasa.

const items = $input.all();
const NOW = Date.now();
const MS_4H = 4 * 3600 * 1000;
const MS_24H = 24 * 3600 * 1000;

const out = [];
for (const item of items) {
  const row = item.json;
  const createdAt = Date.parse(row.created_at);
  if (!createdAt) continue;
  const age = NOW - createdAt;
  if (age < MS_4H) continue;
  if (age >= MS_24H) continue;
  if (row.followup_4h_sent_at) continue;
  if (!row.pending_participants || row.pending_participants.length === 0) continue;
  if (!row.invite_url) continue;
  out.push({ json: row });
}
return out;

// Por cada row, emitir N items (uno por pending phone) con el texto del
// re-recordatorio listo. NOTE: el PATCH del timestamp ya se hizo arriba, esto
// sólo construye el envío.
//
// El nodo Patch 4h timestamp devolvió 204 (return=minimal). Para no perder
// los datos de la row, los leemos de Filter 4h reinvite por nombre.

const rows = $('Filter 4h reinvite').all();
const out = [];
for (const item of rows) {
  const row = item.json;
  for (const pp of (row.pending_participants || [])) {
    const greeting = pp.role === 'lead'
      ? `Hola ${pp.name}, te recordamos el enlace del grupo de la llamada por si no entraste antes: ${row.invite_url}`
      : `Hola ${pp.name}, te recuerdo el enlace al grupo del lead ${row.lead_name} (${row.lead_company}): ${row.invite_url}`;
    out.push({ json: { row_id: row.id, number: pp.phone, text: greeting, name: pp.name, role: pp.role } });
  }
}
return out;

// Filtra rows que llevan >=24h en awaiting_join y no se ha lanzado todavía
// el Slack alert al SDR.

const items = $input.all();
const NOW = Date.now();
const MS_24H = 24 * 3600 * 1000;
const MS_72H = 72 * 3600 * 1000;

const out = [];
for (const item of items) {
  const row = item.json;
  const createdAt = Date.parse(row.created_at);
  if (!createdAt) continue;
  const age = NOW - createdAt;
  if (age < MS_24H) continue;
  if (age >= MS_72H) continue;
  if (row.slack_alert_24h_sent_at) continue;
  out.push({ json: row });
}
return out;

// Filtra rows con >=72h en awaiting_join. Vamos a marcar failed y avisar.

const items = $input.all();
const NOW = Date.now();
const MS_72H = 72 * 3600 * 1000;

const out = [];
for (const item of items) {
  const row = item.json;
  const createdAt = Date.parse(row.created_at);
  if (!createdAt) continue;
  if ((NOW - createdAt) < MS_72H) continue;
  out.push({ json: row });
}
return out;
